import sys
input = sys.stdin.read

def main():
    data = input().split()
    n = int(data[0])
    trophies = data[1]

    # Find all segments of golden trophies
    segments = []
    current_length = 0

    for i in range(n):
        if trophies[i] == 'G':
            current_length += 1
        else:
            if current_length > 0:
                segments.append(current_length)
            current_length = 0

    if current_length > 0:
        segments.append(current_length)

    # If no segments of 'G' exist, the result is 0
    if not segments:
        print(0)
        return

    max_beauty = max(segments)

    # If there's only one segment, check if swapping a single 'S' can extend it
    if len(segments) == 1:
        if segments[0] < n:  # At least one 'S' exists
            print(segments[0] + 1)
        else:
            print(segments[0])
        return

    # Calculate max beauty with at most one swap
    for i in range(len(segments) - 1):
        if segments[i] + segments[i + 1] + 1 <= n:
            max_beauty = max(max_beauty, segments[i] + segments[i + 1] + 1)

    print(max_beauty)

main()

